    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int m = (int) in.nval;
        long[] managers = new long[m];
        long[][] reports = new long[m][];
        for (int i = 0; i < m; i++) {
            in.nextToken(); managers[i] = (long) in.nval;
            in.nextToken(); int k = (int) in.nval;
            reports[i] = new long[k];
            for (int j = 0; j < k; j++) { in.nextToken(); reports[i][j] = (long) in.nval; }
        }
        StringBuilder sb = new StringBuilder();
        for (List<Long> level : orgLevels(managers, reports)) {
            for (int j = 0; j < level.size(); j++) sb.append(level.get(j)).append(j + 1 < level.size() ? " " : "\n");
        }
        System.out.print(sb);
    }
}

