def gen(rng):
    def make(n, idmax, shape):
        ids = rng.sample(range(1, idmax + 1), n)
        kids = {}
        for i in range(1, n):
            if shape == 'chain':
                p = i - 1
            elif shape == 'star':
                p = 0
            elif shape == 'binary':
                p = (i - 1) // 2
            elif shape == 'deep':
                p = max(0, i - 1 - rng.randint(0, 2))
            else:
                p = rng.randrange(i)
            kids.setdefault(p, []).append(ids[i])
        entries = []
        for p, lst in kids.items():
            rng.shuffle(lst)
            entries.append((ids[p], lst))
        rng.shuffle(entries)
        lines = [str(len(entries))]
        for mgr, lst in entries:
            lines.append(f'{mgr} {len(lst)} ' + ' '.join(map(str, lst)))
        return '\n'.join(lines)

    tests = ['1\n1 1 2', '1\n5 2 3 1', '2\n2 1 3\n1 1 2', '5\n2 4 1 10 11 55\n1 3 3 28 13\n13 2 26 9\n11 2 62 31\n9 1 51',
             '3\n10 2 20 30\n20 1 40\n30 1 50', '2\n1000000000 1 1\n7 1 1000000000'.replace('7 1 1000000000', '7 1 1000000000')]
    for _ in range(90):
        n = rng.randint(2, 25)
        shape = rng.choice(['random', 'random', 'chain', 'star', 'binary', 'deep'])
        idmax = rng.choice([n + 3, 100, 10**9])
        tests.append(make(n, idmax, shape))
    n = 50000
    tests.append(make(n, 10**9, 'random'))
    tests.append(make(n, 10**9, 'chain'))
    tests.append(make(n, 10**9, 'star'))
    tests.append(make(n, 10**9, 'binary'))
    tests.append(make(n, 10**9, 'deep'))
    return tests
